export const initialState = {status: "idle"}

export function apiReducer(state, action) {
    switch(action.type) {
        case "FETCH":
            return {status: "loading"};
        
        case "SUCCESS":
            return {status: "success", data: action.payload};
        
        case "ERROR":
            return{status: "error", error: action.payload};

        case "RESET":
            return{status: "idle"};
        
        default:
            return state
    }
}