export function fakePaginatedApi(page, limit = 2) {
    return new Promise((resolve) => {
        setTimeout(() => {
            const start = (page - 1) * limit;

            const data = Array.from({length: limit}, (_, i) => {
                const id = start + i + 1
                return {
                    id,
                    title: `Item ${id}`,
                    image: `https://static.photos/aerial/200x200/${id}`
                }
            })

            resolve({
                data,
                totalPages: 5
            })
        }, 1000);
    })
}