export function fakeApi(shouldFail){
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            if(shouldFail) {
                reject(new Error("Fake API error"));
            }
            else{
                resolve([
                    "React",
                    "JavaScript",
                    "Async logic",
                    "Fake API demo"
                ])
            }
        }, 1000)
    })
}