import React, { forwardRef } from "react";
import "./About.scss"
import about from "../../assets/images/about.png"

const About = forwardRef((props, ref) => {
    return(
        <section className="about" ref={ref}>
            <div className="container">
                <div className="about-image">
                    <img src={about} alt="" />
                </div>
                <div className="about-info">
                    <div className="about-title">About <span>Me</span></div>
                    <div className="about-desc">Привет! Меня зовут Дмитрий. Я фронтенд-разработчик, увлечённый созданием интерактивных и динамичных веб-приложений.<br /><br /> Изначально я начал изучать Angular, где познакомился с основами компонентного подхода и реактивного программирования через RxJS, а затем плавно перешёл на React, чтобы создавать более современный и гибкий интерфейс.

Я уверенно работаю с JavaScript и TypeScript, понимаю работу с состоянием и асинхронной логикой, умею реализовывать интерактивные виджеты и динамические страницы.<br /><br /> Мне нравится делать интерфейсы, которые не только красиво выглядят, но и работают быстро и удобно для пользователя.<br />

Я всегда стремлюсь к чистому и понятному коду, изучаю новые технологии и готов создавать современные решения для веба.</div>
                </div>
            </div>
        </section>
    )
})

export default About