import React, { useEffect, useMemo, useState } from "react";
import { Stage, Container, Sprite, useTick } from "@pixi/react";
import * as PIXI from "pixi.js";

import git from "../../../assets/images/pixi/icon-git.png";
import jsIcon from "../../../assets/images/pixi/icon-javascript.png";
import sassIcon from "../../../assets/images/pixi/icon-sass.png";
import tsIcon from "../../../assets/images/pixi/icon-ts.png";
import reactIcon from "../../../assets/images/pixi/icon-react.png";
import angularIcon from "../../../assets/images/pixi/icon-angular.png";

const ICONS = [git, jsIcon, sassIcon, tsIcon, reactIcon, angularIcon];

function IconsLayer({ count = 10 }) {
  const [sprites, setSprites] = useState([]);

  useMemo(() => {
    setSprites(
      Array.from({ length: count }, (_, i) => ({
        texture: PIXI.Texture.from(ICONS[i % ICONS.length]),
        x: Math.random() * window.innerWidth,
        y: Math.random() * window.innerHeight,
        direction: Math.random() * Math.PI * 2,
        speed: 1 + Math.random() * 2,
        turnSpeed: Math.random() - 0.5,
        scale: 0.01 + Math.random() * 0.2,
        rotation: 0,
      })),
    );
  }, [count]);

  useTick((delta) => {
    const padding = 100;
    const width = window.innerWidth + padding * 2;
    const height = window.innerHeight + padding * 2;

    // мутируем объекты и обновляем состояние
    setSprites((prev) =>
      prev.map((sprite) => {
        let x = sprite.x + Math.sin(sprite.direction) * sprite.speed * delta;
        let y = sprite.y + Math.cos(sprite.direction) * sprite.speed * delta;
        let direction = sprite.direction + sprite.turnSpeed * 0.01;
        let rotation = -direction - Math.PI / 2;

        if (x < -padding) x += width;
        if (x > window.innerWidth + padding) x -= width;
        if (y < -padding) y += height;
        if (y > window.innerHeight + padding) y -= height;

        return { ...sprite, x, y, direction, rotation };
      }),
    );
  });

  return (
    <Container>
      {sprites.map((sprite, i) => (
        <Sprite
          key={i}
          texture={sprite.texture}
          x={sprite.x}
          y={sprite.y}
          scale={sprite.scale}
          rotation={sprite.rotation}
          anchor={0.5}
        />
      ))}
    </Container>
  );
}

export default function PixiIcons() {
  const [size, setSize] = useState({
    width: Math.min(window.innerWidth - 50, 1200),
    height: Math.min(window.innerHeight, 600),
  });

  useEffect(() => {
    const handleResize = () => {
      setSize({
        width: Math.min(window.innerWidth - 50, 1200),
        height: Math.min(window.innerHeight, 600),
      });
    };

    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  return (
    <Stage
      className="pixi"
      width={size.width}
      height={size.height}
      options={{
        backgroundColor: 0xffffff,
        antialias: true,
      }}
    >
      <IconsLayer count={30} />
    </Stage>
  );
}
