import React, { useEffect } from "react";
import "./Projects.scss"
import { useReducer, useState } from "react";
import { apiReducer, initialState } from "./reducer";
import { fakeApi } from "./fakeApi";
import { fakePaginatedApi} from "./fakePaginatedApi"
import { ClipLoader } from "react-spinners";
import { forwardRef } from "react";
import PixiIcons from "./pixi/pixi";

export function FakeApiDemo(){
    const [state, dispatch] = useReducer(apiReducer, initialState)
    const [shouldFail, setShouldFail] = useState(false)

    const fetchData = async () => {
        dispatch({type: "FETCH"})

        try{
            const data = await fakeApi(shouldFail);
            dispatch({type: "SUCCESS", payload: data})
        } catch(e) {
            dispatch({
                type: "ERROR",
                payload: e instanceof Error ? e.message: String(e)
            })
        }
    }

    return (
        <div className="fake-api">
            <div className="fake-api-title">Fake Api</div>
            <label>
                <input type="checkbox" checked={shouldFail} onChange={(e) => setShouldFail(e.target.checked)} />
                Сымитировать ошибку
            </label>
            <div className="fake-api-actions">
                <button className="btn" onClick={fetchData} disabled={state.status === "loading"}>Request data</button>
                <button className="btn" onClick={() => dispatch({type: "RESET"})}>Reset</button>
            </div>
            <div className="fake-api-response">
                {state.status === 'idle' && <p>Ожидание запроса</p>}
                {state.status === 'loading' && <p>Загрузка...</p>}
                {state.status === 'success' && (
                <p>{JSON.stringify(state.data, null, 2)}</p>
                )}
                {state.status === 'error' && (
                <p style={{ color: 'red' }}>{console.log(state.error)}{state.error}</p>
                )}
            </div>
        </div>
    )
}

export function PaginationGallary() {
    const [page, setPage] = useState(1)
    const [items, setItems] = useState([])
    const [totalPages, setTotalPages] = useState(1)

    const [loading, setLoading] = useState(false)
    const [error, setError] = useState(null)

    useEffect(() => {
        let cancelled = false

        async function loadData(){
            setLoading(true)
            setError(null)

            try{
                const res = await fakePaginatedApi(page)
                if(!cancelled){
                    setItems(res.data)
                    setTotalPages(res.totalPages);
                    console.log(res.data)
                }
            } catch (e){
                if(!cancelled){
                    setError(e instanceof Error ? e.message : "Unknown Error")
                }
            } finally{
                if(!cancelled){
                    setLoading(false)
                }
            }
        }

        loadData()

        return () => {
            cancelled = true
        }
    }, [page])

    return(
    <div className="pagination-gallery">
        <div className="pagination-gallery-title">Image Gallery with Pagination</div>

      {loading && <ClipLoader  className="loader"/>}
      {error && <p className="error">{error}</p>}

      <ul className="gallery">
        {items.map(item => (
          <li key={item.id} className="card">
            <img
              src={item.image}
              alt={item.title}
              loading="lazy"
              onError={(e) => {
                e.currentTarget.alt = "Image";
              }}
            />
            <p>{item.title}</p>
          </li>
        ))}
      </ul>

      <div className="actions">
        <button className="btn" onClick={() => setPage(p => p - 1)} disabled={page === 1 || loading} style={page === 1 || loading ? { backgroundColor: "gray", cursor: "not-allowed" } : {}}>
          Prev
        </button>

        <span>
          Page {page} / {totalPages}
        </span>

        <button className="btn" onClick={() => setPage(p => p + 1)} disabled={page === totalPages || loading} style={page === totalPages || loading ? { backgroundColor: "gray", cursor: "not-allowed" } : {}}>
          Next
        </button>
      </div>
    </div>
    )
}

export const Projects = forwardRef((props, ref) => {
    return(
        <section className="projects" ref={ref}>
            <div className="container">
                <div className="projects-title">Projects</div>
                <div className="projects-desc">В этом разделе продемонстрированы некоторые технологии в виде небольшого интерактива</div>
                <div className="project-fake-api">
                    <FakeApiDemo />
                    <div className="project-fake-api-desc">Интерактивный компонент, демонстрирующий работу с асинхронными запросами и управлением состояния в React. Используется useReducer для предсказуемого контроля статусов запроса (idle, loading, success, error) и useState для управления опцией симуляции ошибки.</div>
                </div>
                <div className="project-fake-pagination">
                    <div className="project-fake-pagination-desc">Небольшой виджет галереи изображений с постраничной загрузкой данных. Реализовал асинхронную подгрузку элементов при переключении страниц, обработку состояний загрузки и ошибок, а также блокировку навигации на границах пагинации. Изображения берутся из внешнего сервиса и лениво загружаются для оптимизации производительности. Проект демонстрирует работу с useState, useEffect и асинхронной логикой без использования глобального состояния.</div>
                    <PaginationGallary />
                </div>
                <div className="project-pixi">
                    <div className="project-pixi-title">Interactive Tech Icons</div>
                    <div className="project-pixi-desc">Интерактивная анимация с иконками технологий (React, JavaScript, Angular, TypeScript, Git, Sass) реализована с использованием PixiJS 7 и React.
Иконки динамически генерируются с разными направлениями, скоростью и масштабом, плавно двигаясь по экрану через useTick.
Канвас адаптивно подстраивается под размер окна, создавая современный и живой визуальный элемент для портфолио.</div>
                    <PixiIcons />
                </div>
            </div>
        </section>
    )
})